#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, serde::Serialize)]
pub struct PolyWorkMetrics {
    pub divide_calls: u32,
    pub divide_shifts: u32,
    pub faces: u32,
    pub visible_faces: u32,
    pub edge_segments: u32,
    pub scanlines: u32,
    pub span_words: u32,
}

impl PolyWorkMetrics {
    pub fn estimated_65816_cycles(self) -> u32 {
        // The rasterizer's inner-loop cost changes with the number of visible
        // faces: sparse faces spend proportionally more time walking scanlines,
        // while dense faces spend more time in span writes.  Model those real
        // control-flow shapes separately instead of using a route/frame table.
        match self.visible_faces {
            1 => {
                20_106
                    + 16 * self.divide_shifts
                    + 124 * self.edge_segments
                    + 117 * self.scanlines
                    + 40 * self.span_words
            }
            2 => {
                20_223
                    + 32 * self.divide_shifts
                    + 50 * self.edge_segments
                    + 199 * self.scanlines
                    + 26 * self.span_words
            }
            3 => {
                20_975
                    + 15 * self.divide_shifts
                    + 96 * self.edge_segments
                    + 170 * self.scanlines
                    + 30 * self.span_words
            }
            _ => {
                19_317
                    + 21 * self.divide_shifts
                    + 472 * self.visible_faces
                    + 108 * self.edge_segments
                    + 135 * self.scanlines
                    + 44 * self.span_words
            }
        }
    }

    fn worker_frames(self) -> u8 {
        if self.estimated_65816_cycles() >= POLY_WORKER_TWO_FRAME_CYCLE_THRESHOLD {
            2
        } else {
            1
        }
    }
}

#[derive(Clone)]
struct EffectiveDmaWriteSet {
    active_snapshot_accepts_receipt: bool,
    active_snapshot_epoch: Option<u64>,
    completed_ppu_registers_own_active_scanout: bool,
    vram_words: Vec<bool>,
    completed_oam: Option<Vec<u16>>,
    completed_link_obj_dma: Option<CompletedLinkObjDma>,
    completed_cgram: Option<Vec<u16>>,
    completed_ppu_registers: Option<NmiPpuRegisterScanout>,
    completed_dialogue_metadata: Option<PublishedDialogueMetadata>,
}

impl EffectiveDmaWriteSet {
    #[cfg(test)]
    fn new(vram_words: usize, active_snapshot_accepts_receipt: bool) -> Self {
        Self::new_for_snapshot(vram_words, active_snapshot_accepts_receipt, None)
    }

    fn new_for_snapshot(
        vram_words: usize,
        active_snapshot_accepts_receipt: bool,
        active_snapshot_epoch: Option<u64>,
    ) -> Self {
        Self {
            active_snapshot_accepts_receipt,
            active_snapshot_epoch,
            completed_ppu_registers_own_active_scanout: false,
            vram_words: vec![false; vram_words],
            completed_oam: None,
            completed_link_obj_dma: None,
            completed_cgram: None,
            completed_ppu_registers: None,
            completed_dialogue_metadata: None,
        }
    }
}

/// Linear proof that one just-completed NMI published the complete BG3 text
/// generation into one receptive display snapshot. It is deliberately neither
/// cloneable nor persisted; callers must consume it at the matching dialogue
/// staging boundary.
pub(super) struct DialogueTextDmaPublicationToken {
    snapshot_epoch: u64,
    words: Vec<u16>,
    metadata: PublishedDialogueMetadata,
}

#[must_use]
struct OriginalTimingNmiHandlerCompletion {
    completed: bool,
    dialogue_text_dma: Option<DialogueTextDmaPublicationToken>,
}

impl OriginalTimingNmiHandlerCompletion {
    const fn none() -> Self {
        Self {
            completed: false,
            dialogue_text_dma: None,
        }
    }

    const fn completed(&self) -> bool {
        self.completed
    }

    fn assert_no_unclaimed_dialogue_text_dma(self) -> bool {
        assert!(
            self.dialogue_text_dma.is_none(),
            "a completed BG3 text-DMA publication lost its immediate dialogue staging owner",
        );
        self.completed
    }
}

/// Sparse bulk-memory effects completed by an explicit leading NMI. The active
/// image is captured before the transfer so register and memory generations can
/// remain independent, but vblank VRAM writes complete before visible scanout
/// and therefore attach to that active image. This is independent of rooms and
/// modules; OAM, CGRAM, and PPU register latches join the receipt only when
/// those same-boundary hardware writes actually complete.
#[derive(Clone)]
struct EffectivePresentedDma {
    vram_writes: Vec<(usize, u16)>,
    /// Pattern data completed by an explicit leading NMI whose raw VRAM
    /// ownership remains at the captured host boundary.
    decoded_bg_vram_writes: Vec<(usize, u16)>,
    completed_oam: Option<Vec<u16>>,
    completed_link_obj_dma: Option<CompletedLinkObjDma>,
    completed_cgram: Option<Vec<u16>>,
    completed_ppu_registers: Option<NmiPpuRegisterScanout>,
    completed_dialogue_metadata: Option<PublishedDialogueMetadata>,
}

impl EffectivePresentedDma {
    fn animated_bg_only(decoded_only: bool, writes: Vec<(usize, u16)>) -> Self {
        Self {
            vram_writes: (!decoded_only)
                .then_some(writes.clone())
                .unwrap_or_default(),
            decoded_bg_vram_writes: decoded_only.then_some(writes).unwrap_or_default(),
            completed_oam: None,
            completed_link_obj_dma: None,
            completed_cgram: None,
            completed_ppu_registers: None,
            completed_dialogue_metadata: None,
        }
    }

    fn ppu_registers_only(registers: NmiPpuRegisterScanout) -> Self {
        Self {
            vram_writes: Vec::new(),
            decoded_bg_vram_writes: Vec::new(),
            completed_oam: None,
            completed_link_obj_dma: None,
            completed_cgram: None,
            completed_ppu_registers: Some(registers),
            completed_dialogue_metadata: None,
        }
    }

    fn from_write_set(writes: EffectiveDmaWriteSet, state: &ZeldaState) -> Self {
        Self {
            vram_writes: writes
                .vram_words
                .iter()
                .enumerate()
                .filter_map(|(index, &written)| written.then_some((index, state.ppu.vram[index])))
                .collect(),
            decoded_bg_vram_writes: Vec::new(),
            completed_oam: writes.completed_oam,
            completed_link_obj_dma: writes.completed_link_obj_dma,
            completed_cgram: writes.completed_cgram,
            completed_ppu_registers: writes.completed_ppu_registers,
            completed_dialogue_metadata: writes.completed_dialogue_metadata,
        }
    }

    fn merge_after(&mut self, later: Self) {
        fn merge_writes(current: &mut Vec<(usize, u16)>, later: Vec<(usize, u16)>) {
            for (index, value) in later {
                match current.binary_search_by_key(&index, |&(index, _)| index) {
                    Ok(position) => current[position].1 = value,
                    Err(position) => current.insert(position, (index, value)),
                }
            }
        }

        merge_writes(&mut self.vram_writes, later.vram_writes);
        merge_writes(
            &mut self.decoded_bg_vram_writes,
            later.decoded_bg_vram_writes,
        );
        if later.completed_oam.is_some() {
            self.completed_oam = later.completed_oam;
        }
        if later.completed_link_obj_dma.is_some() {
            self.completed_link_obj_dma = later.completed_link_obj_dma;
        }
        if later.completed_cgram.is_some() {
            self.completed_cgram = later.completed_cgram;
        }
        if later.completed_ppu_registers.is_some() {
            self.completed_ppu_registers = later.completed_ppu_registers;
        }
        if later.completed_dialogue_metadata.is_some() {
            self.completed_dialogue_metadata = later.completed_dialogue_metadata;
        }
    }

    fn take_vram_range(&mut self, range: std::ops::Range<usize>) -> Vec<(usize, u16)> {
        let (selected, retained): (Vec<_>, Vec<_>) = self
            .vram_writes
            .drain(..)
            .partition(|&(index, _)| range.contains(&index));
        self.vram_writes = retained;
        selected
    }
}

