    fn debug_latch_frame_matches(&self) -> bool {
        static RANGE: std::sync::OnceLock<Option<(u32, u32)>> = std::sync::OnceLock::new();
        let Some((lo, hi)) = RANGE.get_or_init(|| {
            let value = std::env::var("ZELDA3_DEBUG_LATCH").ok()?;
            let (lo, hi) = value.split_once('-')?;
            Some((lo.parse().ok()?, hi.parse().ok()?))
        }) else {
            return false;
        };
        (*lo..=*hi).contains(&self.frame_ctr_dbg)
    }

    /// `ZELDA3_DEBUG_LATCH=<lo>-<hi>` traces every software NMI-latch
    /// set/clear with its `#[track_caller]` provenance for hosts in range —
    /// the direct probe for latch-disposition divergences.
    #[track_caller]
    pub(crate) fn latch_nmi_update(&mut self) {
        if self.debug_latch_frame_matches() {
            eprintln!(
                "[LATCH] set host={} caller={}",
                self.frame_ctr_dbg,
                core::panic::Location::caller()
            );
        }
        self.display_core_mut().latch_nmi_update();
    }

    #[track_caller]
    pub(crate) fn clear_nmi_update_latch(&mut self) {
        if self.debug_latch_frame_matches() {
            eprintln!(
                "[LATCH] clear host={} caller={}",
                self.frame_ctr_dbg,
                core::panic::Location::caller()
            );
        }
        self.display_core_mut().clear_nmi_update_latch();
    }

    pub(super) fn take_dungeon_landing_cpu_advance(&mut self) -> Option<DungeonModuleCpuAdvance> {
        let advance = self.dungeon_landing_cpu_advance_pending.take();
        self.active_dungeon_landing_spotlight_reset_prefix_scanlines =
            self.dungeon_landing_spotlight_reset_prefix_scanlines.take();
        advance
    }

    pub(super) fn begin_dungeon_landing_spotlight_publication(
        &mut self,
        entry_started_after_leading_nmi: bool,
    ) {
        self.interrupted_dungeon_spotlight_build_in_flight = None;
        self.last_completed_interrupted_dungeon_spotlight_scanout = None;
        self.dungeon_landing_entry_started_after_leading_nmi = entry_started_after_leading_nmi;
        self.dungeon_landing_spotlight_reset_prefix_scanlines = None;
        self.active_dungeon_landing_spotlight_reset_prefix_scanlines = None;
    }

    pub(super) fn take_dungeon_cached_sprite_cpu_interruption(
        &mut self,
    ) -> Option<(CachedSpriteCpuInterruption, Option<OriginalTimingBoundary>)> {
        self.dungeon_cached_sprite_cpu_interruption_pending
            .take()
            .map(|interruption| {
                (
                    interruption,
                    self.dungeon_cached_sprite_cpu_interruption_boundary.take(),
                )
            })
    }

    pub(super) fn capture_cpu_schedules_before_nmi(&mut self) {
        let frame = self.game_state.frame;
        if self.rom_startup_timing()
            && frame.main_module == 9
            && matches!(frame.submodule, 0x20 | 0x21)
            && self.game_execution_scheduler.is_idle()
            && self.module09_cpu_schedule.is_none()
        {
            self.module09_cpu_schedule = Some(module09_cpu_schedule(self));
        }
        if self.rom_startup_timing()
            && frame.main_module == 7
            && frame.submodule == 2
            && frame.subsubmodule == 12
        {
            if self.dungeon_landing_cpu_advance_pending.is_none() {
                let advance = begin_dungeon_supertile_state_12_cpu_advance(self);
                self.dungeon_landing_spotlight_reset_prefix_scanlines = None;
                self.dungeon_landing_cpu_advance_pending = Some(advance);
            }
        }
        if self.rom_startup_timing()
            && frame.main_module == 7
            && ((frame.submodule == 0x0e && matches!(frame.subsubmodule, 3 | 6 | 7 | 19))
                || (frame.submodule == 2 && frame.subsubmodule == 3))
            && self.game_execution_scheduler.is_idle()
            && self.dungeon_submodule_cpu_schedule.is_none()
        {
            let schedule = dungeon_submodule_cpu_schedule(self);
            if env::var_os("ZELDA3_DEBUG_DUNGEON_CPU_SCHEDULE").is_some() {
                eprintln!(
                    "dungeon_cpu_schedule host={} module={:02x}/{:02x}/{:02x} submodule_nmis={} caller_nmis={} sprite_main_nmis={} suffix_nmis={} caller_phase={:?} sprite_boundary={:?} cached_boundary={:?} reenters_main={}",
                    self.frame_ctr_dbg,
                    frame.main_module,
                    frame.submodule,
                    frame.subsubmodule,
                    schedule.submodule_nmis,
                    schedule.caller_nmis,
                    schedule.caller_sprite_main_nmis,
                    schedule.caller_suffix_nmis,
                    schedule.caller_first_nmi_phase,
                    schedule.sprite_main_boundary,
                    schedule.cached_sprite_interruption,
                    schedule.reenters_main_loop_before_nmi,
                );
            }
            self.dungeon_submodule_cpu_schedule = Some(schedule);
        }
    }

    pub(super) fn suspend_dungeon_subtile_palette_filter_if_cpu_interrupted(&mut self) {
        let Some(advance) = self.dungeon_palette_cpu_advance_pending.take() else {
            return;
        };
        debug_assert_eq!(
            advance.subsubmodule, self.game_state.frame.subsubmodule,
            "subtile palette ROM shadow and translated body disagree at PC {:06x}",
            advance.pc,
        );
        debug_assert_eq!(
            advance.palette_countdown,
            self.game_state.display.palette_filter.countdown(),
            "subtile palette ROM shadow and translated palette disagree at PC {:06x}",
            advance.pc,
        );
        if advance.work.reached_boundary().is_some() {
            // Every typed main-loop interruption is after the Module 7
            // submodule returned. If the continuous source owner reached
            // Sprite_Main, LinkOam, or sprite preparation in this same host,
            // the native CPU estimate's earlier palette-return suspension is
            // obsolete. Keep the later receipt on the bus for its actual
            // translated caller; only suppress this superseded timing shadow.
            if matches!(self.original_timing_owner, OriginalTimingOwnerState::Live)
                && self.original_timing_main_loop_interruption().is_some()
            {
                return;
            }
            if self.original_timing_owes_sprite_main_return()
                || self.original_timing_owes_sprite_main_progress()
            {
                // The live wire still owes this host its Sprite_Main return
                // claim — or a mid-body checkpoint proving the caller runs
                // into Sprite_Main before the host ends — so the caller
                // cannot be suspended before that body runs; the estimate's
                // vblank crossing is superseded (route hosts 32372, 85627).
                return;
            }
            self.game_execution_scheduler.schedule_work(
                GameWorkContinuation::FinishDungeonSubtilePaletteFilter,
                DUNGEON_SUBTILE_PALETTE_FILTER_RETURN_NMI_SLICES,
            );
        }
    }

    pub(super) fn suspend_straight_interroom_fadeout_suffix_if_crosses_nmi(
        &mut self,
        palette_countdown: u8,
    ) {
        let frame = self.game_state.frame;
        if self.rom_startup_timing()
            && straight_interroom_fadeout_suffix_crosses_vblank(
                frame.main_module,
                frame.submodule,
                frame.subsubmodule,
                self.game_state.world.location.dungeon_room_index(),
                self.game_state.dungeon.stair_movement.staircase_index(),
                palette_countdown,
            )
        {
            if matches!(self.original_timing_owner, OriginalTimingOwnerState::Live)
                && self
                    .original_timing_semantic_receipts
                    .as_ref()
                    .is_some_and(|receipts| {
                        receipts.semantic().iter().any(|receipt| {
                            *receipt == OriginalTimingSemanticReceipt::SpriteMainReturned
                        })
                    })
            {
                // The live wire still owes this host its Sprite_Main return
                // claim, so the Module 7 caller cannot be suspended before
                // that body runs; the estimate's vblank crossing is
                // superseded (route host 25863).
                return;
            }
            self.game_execution_scheduler.schedule_work(
                GameWorkContinuation::FinishStraightInterroomFadeoutSuffix,
                DUNGEON_SUBTILE_PALETTE_FILTER_RETURN_NMI_SLICES,
            );
        }
    }

    /// Stage the next frame's OBJ scanout generations, recording the caller's
    /// source location so the display probe (`ZELDA3_DEBUG_DISPLAY_OAM_FRAME` /
    /// `ZELDA3_DEBUG_DISPLAY_OBJ_VRAM_FRAME`) can name which handler owns the
    /// decision. Every writer of `next_display_obj_scanout_generation` should go
    /// through here rather than assigning the field directly.
    #[track_caller]
    fn set_next_display_obj_scanout(&mut self, value: Option<ObjScanoutGenerations>) {
        if value.is_some() {
            self.next_display_obj_scanout_provenance = Some(core::panic::Location::caller());
        }
        self.next_display_obj_scanout_generation = value;
    }

    /// Record the OAM consequence of an NMI that interrupted Sprite_Main.
    /// Interrupt_NMI either retains hardware OAM when its software latch is
    /// set, or NMI_DoUpdates copies the exact live $0800..$0a1f shadow.
    pub(super) fn stage_interrupted_sprite_main_oam_scanout(&mut self) {
        if !self.rom_startup_timing() {
            return;
        }
        if self.ram[crate::game_state::constants::NMI_BOOLEAN] != 0 {
            // Interrupt_NMI skips NMI_DoUpdates while the software latch is
            // already set. No $2104 DMA occurs, so the resident hardware OAM
            // table survives this vblank verbatim. Display capture versions
            // that table through resident_oam_dma, which advances only on a
            // real $2104 transfer.
            self.set_next_display_obj_scanout(Some(ObjScanoutGenerations {
                oam: OamScanoutSource::RetainResidentPpuOam,
                link_obj: GraphicsDmaGeneration::HostBoundaryBeforeMain,
                link_obj_sources: GraphicsDmaGeneration::HostBoundaryBeforeMain,
            }));
            return;
        }
        let oam = self
            .sprite_oam_shadow_buffer()
            .chunks_exact(2)
            .take(self.ppu.oam.len())
            .map(|bytes| u16::from_le_bytes([bytes[0], bytes[1]]))
            .collect();
        self.next_display_obj_memory_generation =
            Some(DisplayObjGeneration::RetainCapturedOam { oam });
        self.set_next_display_obj_scanout(Some(ObjScanoutGenerations {
            oam: OamScanoutSource::ComposeInterruptedSpriteMainShadowDma,
            link_obj: GraphicsDmaGeneration::HostBoundaryBeforeMain,
            link_obj_sources: GraphicsDmaGeneration::HostBoundaryBeforeMain,
        }));
    }

    /// A saved Sprite_Main stack resumes during active display and returns to
    /// the ordinary ZeldaRunGameLoop suffix. The capture preceding its trailing
    /// NMI still owns the resident OAM and host-boundary Link OBJ generation;
    /// the DMA performed by that trailing NMI belongs to the following field.
    fn stage_resumed_sprite_main_return_obj_scanout(&mut self) {
        self.set_next_display_obj_scanout(Some(ObjScanoutGenerations {
            oam: OamScanoutSource::RetainResidentPpuOam,
            link_obj: GraphicsDmaGeneration::HostBoundaryBeforeMain,
            link_obj_sources: GraphicsDmaGeneration::HostBoundaryBeforeMain,
        }));
    }

    pub(super) fn stage_straight_interroom_fadeout_obj_source(&mut self) {
        if self.next_display_obj_scanout_generation.is_some() {
            // A resumed caller already staged the independently measured OAM
            // and Link-DMA generations for this capture.
            return;
        }
        let mut scanout = straight_interroom_fadeout_obj_scanout();
        // Link's raw VRAM scanout can be live while its semantic source still
        // belongs to the host-boundary operands consumed by the NMI. Preserve
        // the ordinary atomic fadeout snapshot explicit.
        scanout.link_obj_sources = GraphicsDmaGeneration::HostBoundaryBeforeMain;
        self.set_next_display_obj_scanout(Some(scanout));
    }

    pub(super) fn suspend_spiral_staircase_palette_filter(
        &mut self,
        tail: SpiralStaircasePaletteTail,
    ) -> bool {
        if !self.rom_startup_timing() {
            return false;
        }
        // The interrupted palette walk keeps NMI_DoUpdates gated until the
        // translated caller returns. In particular, the animated-BG DMA must
        // not consume the source advanced by the suspended spiral-staircase
        // main slice.
        self.set_core_update_disable_flag(1);
        let caller =
            InterruptedPaletteFilterCaller::from_dungeon_submodule(self.game_state.frame.submodule);
        self.game_execution_scheduler.schedule_work(
            GameWorkContinuation::FinishSpiralStaircasePaletteFilter { tail, caller },
            DUNGEON_SUBTILE_PALETTE_FILTER_RETURN_NMI_SLICES,
        );
        true
    }

    pub(super) fn suspend_straight_interroom_sprite_reset_before_room_load(&mut self) -> bool {
        if !self.rom_startup_timing() {
            return false;
        }
        let Some(receipt) = self.take_original_timing_dungeon_reset_sprites_progress() else {
            return false;
        };
        let progress = receipt.progress;

        // The replaceable authority reports the source statement reached when
        // this host interval returned.  Apply that prefix exactly and carry
        // the typed token into the continuation; no room, staircase, raster,
        // or emulator-program-counter selector belongs in translated code.
        let dungeon_room_index = self.game_state.world.location.dungeon_room_index();
        self.dungeon_room_tracking_mut()
            .set_room_index2(dungeon_room_index);
        self.dungeon_reset_sprites_through_cpu_progress(progress);
        let continuation = GameWorkContinuation::FinishStraightInterroomSpriteReset { progress };
        match receipt.boundary {
            OriginalTimingBoundary::HostReturn => {
                self.game_execution_scheduler.schedule_work(continuation, 1);
            }
            OriginalTimingBoundary::NmiAccepted => self
                .game_execution_scheduler
                .schedule_after_current_trailing_nmi(continuation),
        }
        true
    }

    fn complete_straight_interroom_sprite_reset_after_timing_boundary(
        &mut self,
        progress: DungeonResetSpritesCpuProgress,
    ) {
        self.complete_straight_interroom_sprite_reset_body(progress);
        self.retire_or_run_main_loop_common_suffix_after_module_return();
    }

    /// The resumed `Dungeon_ResetSprites` caller through Module07's suffix,
    /// without the shared ZeldaRunGameLoop suffix (a typed terminal return
    /// retires that itself; route host 307622).
    fn complete_straight_interroom_sprite_reset_body(
        &mut self,
        progress: DungeonResetSpritesCpuProgress,
    ) {
        let progress = self.refine_dungeon_reset_progress_before_resume(progress);
        self.dungeon_resume_reset_sprites_after_cpu_progress(progress);
        // This caller crossed its leading display boundary inside
        // Dungeon_ResetSprites. Keep that execution provenance after the
        // one-shot continuation is consumed so the later quadrant-upload
        // states retain the same NMI-first cadence.
        self.game_execution_scheduler
            .begin_leading_nmi_upload_pipeline();
        self.complete_module07_dungeon_after_submodule();
    }

    fn refine_dungeon_reset_progress_before_resume(
        &mut self,
        completed: DungeonResetSpritesCpuProgress,
    ) -> DungeonResetSpritesCpuProgress {
        let Some(receipt) = self.take_original_timing_dungeon_reset_sprites_progress() else {
            return completed;
        };
        assert_eq!(
            receipt.boundary,
            OriginalTimingBoundary::NmiAccepted,
            "a queued Dungeon_ResetSprites caller may refine only at its accepting NMI",
        );
        assert!(
            self.dungeon_advance_reset_sprites_cpu_progress(completed, receipt.progress),
            "timing authority published an unsupported Dungeon_ResetSprites progress transition",
        );
        receipt.progress
    }

    pub(super) fn schedule_dungeon_faded_filter_completion_nmi(&mut self) {
        debug_assert!(self.rom_startup_timing());
        debug_assert_eq!(self.game_state.frame.main_module, 7);
        debug_assert_eq!(self.game_state.frame.submodule, 2);
        debug_assert_eq!(self.game_state.frame.subsubmodule, 3);
        debug_assert_eq!(self.game_state.display.palette_filter.countdown(), 0);
        self.stage_dungeon_faded_filter_completion_scanout();
        self.schedule_dungeon_faded_filter_leading_nmi_resume();
    }

    fn schedule_dungeon_faded_filter_leading_nmi_resume(&mut self) {
        debug_assert!(self.rom_startup_timing());
        debug_assert_eq!(self.game_state.frame.main_module, 7);
        debug_assert_eq!(self.game_state.frame.submodule, 2);
        self.game_execution_scheduler.schedule_pre_main_nmi_resume(
            PreMainNmiResume::DungeonModuleCallerCompletedBeforeNextNmi,
        );
    }

    fn stage_spiral_stairs_second_grayscale_nmi(&mut self) -> GraphicsDmaGeneration {
        // The final quadrant-upload NMI has returned, so the atomic ROM path
        // exposes $0710 = 0 to this caller. Its core DMA is allowed to run.
        // The resident animated batch remains visible for this image. When
        // this suffix consumes countdown 1 it advances $0adc before NMI, so
        // the DMA must use the live operand even though its result belongs to
        // the following scanout.
        self.clear_core_update_disable_flag();
        self.next_display_animated_bg_scanout_generation =
            Some(AnimatedBgScanoutGeneration::HostBoundaryBeforeNmi);
        if self.game_state.display.bg_tile_animation_countdown == 1 {
            GraphicsDmaGeneration::LiveAfterMain
        } else {
            GraphicsDmaGeneration::HostBoundaryBeforeMain
        }
    }

    /// Env-gated provenance for the presented Link OBJ CHR latch: every
    /// assignment logs its call site under `ZELDA3_DEBUG_OBJ_LATCH=<frames>`,
    /// naming the rule that authored a frame's presented OBJ memory in one
    /// probe (the CHR-domain counterpart of the OBJ-scanout staged_by tool).
    #[track_caller]
    pub(crate) fn set_obj_vram_latch_traced(&mut self, value: Option<Vec<u16>>) {
        if nmi::debug_frame_selection_env_matches("ZELDA3_DEBUG_OBJ_LATCH", self.frame_ctr_dbg) {
            let sample = value
                .as_deref()
                .map(|latch| latch.get(0x4020).copied().unwrap_or(0));
            eprintln!(
                "obj_latch host={} some={} w4020={:04x?} caller={}",
                self.frame_ctr_dbg,
                value.is_some(),
                sample,
                std::panic::Location::caller()
            );
        }
        self.ppu.obj_vram_latch = value;
    }

    /// Env-gated tracer for the presented Link OBJ CHR pipeline: under
    /// `ZELDA3_DEBUG_OBJ_PIPE=<frames>` each stage (NMI bracket, snapshot
    /// capture/publication, staging, promotion) logs a fingerprint of the OBJ
    /// page ($4000-$43ff) so the snapshot generation feeding a scanout can be
    /// followed end to end. `page` is the OBJ page slice itself.
    fn debug_obj_pipe_enabled(&self) -> bool {
        nmi::debug_frame_selection_env_matches("ZELDA3_DEBUG_OBJ_PIPE", self.frame_ctr_dbg)
    }

    pub(crate) fn debug_obj_pipe(&self, stage: &str, page: &[u16]) {
        if !self.debug_obj_pipe_enabled() {
            return;
        }
        let sum: u64 = page.iter().map(|&word| u64::from(word)).sum();
        let sample = |offset: usize| page.get(offset).copied().unwrap_or(0);
        eprintln!(
            "objpipe host={} stage={stage} pack={:04x} sum={sum:08x} w4020={:04x} w4030={:04x} w40b0={:04x} w4120={:04x}",
            self.frame_ctr_dbg,
            read_le_u16(&self.ram, 0x100),
            sample(0x20),
            sample(0x30),
            sample(0xb0),
            sample(0x120),
        );
    }

    fn link_obj_dma_phase_generations(&self) -> LinkObjDmaPhaseGenerations {
        let exit_frame = self.game_state.frame;
        let entry_frame = self
            .pre_main_graphics_dma
            .as_ref()
            .map(|graphics| graphics.entry_frame)
            .unwrap_or(exit_frame);
        let operands = link_obj_operands_across_main(
            entry_frame,
            exit_frame,
            rom_graphics_dma_plan(exit_frame.main_module, exit_frame.submodule).link_obj_operands,
        );
        let mut generations = link_obj_dma_generations_for_cpu_phase(
            self.game_execution_scheduler
                .resumed_call_stack_is_before_nmi(),
            operands,
        );
        if self
            .item_receipt_completion_live_link_dma_host
            .is_some_and(|host| host.wrapping_add(1) == self.frame_ctr_dbg)
        {
            // First NMI after a ground A-press receipt completion. C's chain:
            // LinkOam_Main assigns link_dma_graphics_index from the receipt's
            // new pose, and the prep (misc.c:399) turns it into
            // dma_source_addr_3/_4 — so the sources this NMI consumes were
            // authored by the iteration that just ran, not by the stale host
            // boundary captured before the receipt (f4587 CHR). Upload lane
            // only: the upload is visible from the FOLLOWING scanout, so the
            // presented generation keeps its cadence (f10039).
            generations.following_nmi = GraphicsDmaGeneration::LiveAfterMain;
        }
        generations
    }

    /// Link OBJ generation which had actually completed DMA when the current
    /// scanout was published. A resumed caller may already have authored the
    /// following source, but it is not presented until its NMI completes.
    fn presented_link_obj_dma_generation(&self) -> GraphicsDmaGeneration {
        self.link_obj_dma_phase_generations().presented
    }

    /// Link OBJ operands consumed if the following NMI runs after this CPU
    /// slice. This is intentionally distinct from the presented generation.
    fn following_nmi_link_obj_dma_generation(&self) -> GraphicsDmaGeneration {
        self.link_obj_dma_phase_generations().following_nmi
    }

